CALIBRATION_HTML = r'''<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Potato Calibration</title>
  <script src="https://cdn.jsdelivr.net/npm/gsap@3.13.0/dist/gsap.min.js"></script>
  <script src="https://unpkg.com/lucide@0.468.0/dist/umd/lucide.min.js"></script>
  <style>
    :root{--ink:#17201c;--muted:#69736d;--line:#dce2de;--paper:#f7f8f6;--white:#fff;--green:#176b4b;--mint:#dff3e8;--red:#a63e35;--amber:#a06112;--blue:#245f8c;--shadow:0 10px 30px rgba(23,32,28,.08)}
    *{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;letter-spacing:0}button,input,textarea{font:inherit}button{cursor:pointer}
    header{height:64px;background:var(--ink);color:white;display:flex;align-items:center;padding:0 28px;gap:14px;position:sticky;top:0;z-index:10}.brand{font-size:17px;font-weight:700}.header-state{margin-left:auto;color:#b8c6bf;font-size:12px}
    .layout{display:grid;grid-template-columns:290px minmax(0,1fr);min-height:calc(100vh - 64px)}aside{border-right:1px solid var(--line);background:#eef1ee;padding:22px 16px}.agent-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;margin-bottom:12px}.agent-tabs button{border:0;background:transparent;padding:8px 4px;color:var(--muted);border-bottom:2px solid transparent}.agent-tabs button.active{color:var(--ink);border-color:var(--green);font-weight:700}.sidebar-actions{display:flex;align-items:center;gap:8px;margin-bottom:14px}.new-session{flex:1;border:1px solid var(--ink);background:var(--ink);color:#fff;border-radius:4px;padding:8px 10px;font-weight:650}.archive-toggle{display:flex;align-items:center;gap:5px;color:var(--muted);font-size:11px;white-space:nowrap}.archive-toggle input{width:auto}
    .session-list{display:grid;gap:6px}.session{width:100%;text-align:left;border:1px solid transparent;background:transparent;padding:11px 12px;border-radius:6px;color:var(--ink)}.session:hover{background:#fff}.session.active{background:#fff;border-color:#cbd6cf;box-shadow:0 3px 12px rgba(20,35,27,.06)}.session small{display:block;color:var(--muted);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
    main{padding:28px 34px 60px;max-width:1180px;width:100%;margin:0 auto}.empty{padding:80px 20px;text-align:center;color:var(--muted)}.page-head{display:flex;align-items:flex-start;gap:20px;margin-bottom:24px}.page-head h1{font-size:25px;line-height:1.25;margin:0 0 7px}.page-head p{margin:0;color:var(--muted)}.page-actions{margin-left:auto;display:flex;align-items:center;gap:8px}.status{padding:5px 9px;border-radius:4px;background:var(--mint);color:var(--green);font-weight:700;font-size:12px}.status.closed{background:#e8ebe9;color:#68716c}.danger{border:1px solid #d6b5b0;background:white;color:var(--red);border-radius:4px;padding:7px 10px}.refresh{border:1px solid #bcc7c0;background:white;color:var(--ink);border-radius:4px;padding:7px 10px}
    .progress{display:grid;grid-template-columns:repeat(var(--steps,4),1fr);margin-bottom:24px;border:1px solid var(--line);background:white}.step{padding:14px 15px;border-right:1px solid var(--line)}.step:last-child{border:0}.step b{display:block;font-size:12px}.step span{color:var(--muted);font-size:11px}.step.done{box-shadow:inset 0 3px var(--green)}.step.current{box-shadow:inset 0 3px var(--amber);background:#fffaf1}
    .module{border-top:1px solid var(--line);background:white}.module:last-child{border-bottom:1px solid var(--line)}.module-head{width:100%;border:0;background:white;display:flex;align-items:center;gap:11px;padding:17px 16px;text-align:left}.module-head:hover{background:#fafbf9}.module-head strong{font-size:15px}.module-head .count{color:var(--muted);font-size:12px}.chevron{margin-left:auto;transition:transform .2s}.module.open .chevron{transform:rotate(180deg)}.module-body{display:none;padding:0 16px 20px;overflow:hidden}.module.open .module-body{display:block}
    .execution{border-left:3px solid #cbd6cf;padding:3px 0 3px 15px;margin:12px 0 24px}.execution h3{font-size:14px;margin:0 0 6px}.meta{display:flex;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:12px}.reply{white-space:pre-wrap;background:#f5f7f5;padding:13px;margin-top:12px;border-radius:4px;max-height:260px;overflow:auto}.assets{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px;margin-top:14px}video{width:100%;max-height:500px;background:#111;border-radius:4px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.primary,.secondary,.icon-btn{border:1px solid var(--ink);border-radius:4px;padding:8px 12px;background:var(--ink);color:white;display:inline-flex;align-items:center;gap:7px}.secondary{background:white;color:var(--ink);border-color:#bcc7c0}.primary:disabled{opacity:.45;cursor:not-allowed}.run-form{border:1px solid var(--line);background:#fafbf9;padding:14px;margin:5px 0 20px}.run-form h3{font-size:13px;margin:0 0 9px}.run-form textarea{min-height:86px}
    .review-head{display:flex;align-items:center;gap:12px}.score{font-size:34px;font-weight:750;color:var(--green)}.verdict{font-weight:700}.hard{border-left:3px solid var(--red);padding:10px 12px;background:#fff7f6;margin:8px 0}.style{border-left:3px solid var(--blue);padding:10px 12px;background:#f5f9fc;margin:8px 0}.evidence-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px;margin-top:12px}.evidence-grid figure{margin:0}.evidence-grid img{width:100%;aspect-ratio:16/10;object-fit:cover;background:#e4e8e5;border-radius:4px}.evidence-grid figcaption{font-size:11px;color:var(--muted);margin-top:4px}
    .columns{display:grid;grid-template-columns:1fr 1fr;gap:22px}.columns h3{font-size:13px;margin:0 0 10px}.turn{padding:9px 0;border-bottom:1px solid #edf0ee}.turn b{display:block;font-size:11px;color:var(--muted)}textarea,input,select{width:100%;border:1px solid #bdc7c1;border-radius:4px;padding:10px;background:white;color:var(--ink)}textarea{min-height:100px;resize:vertical}.candidate-form{display:grid;gap:10px}.candidate-intro{border:1px solid var(--line);background:#fafbf9;padding:14px;margin-bottom:14px}.candidate-intro h3{margin:0 0 5px;font-size:14px}.generation-notice{display:flex;align-items:flex-start;gap:9px;padding:10px 11px;border-left:3px solid var(--blue);background:#f5f9fc}.generation-notice i{flex:none;margin-top:2px}.generation-notice strong{display:block}.generation-notice span{display:block;color:var(--muted);font-size:12px;margin-top:2px}.generation-notice.good{border-color:var(--green);background:#f1f8f4}.generation-notice.bad{border-color:var(--red);background:#fff7f6}.generation-notice.running i{animation:spin 1.2s linear infinite}.generation-notice .secondary{margin-left:auto;flex:none}.version-list{display:grid;gap:12px}.version-card{border:1px solid var(--line);padding:14px;background:#fff}.version-head{display:flex;align-items:flex-start;gap:12px}.version-head h3{font-size:14px;margin:0 0 4px}.version-head .status{margin-left:auto}.flow-steps{display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin:13px 0}.flow-step{padding:7px 8px;background:#f0f2f0;color:var(--muted);font-size:11px;text-align:center;border-top:2px solid #cbd2ce}.flow-step.done{background:#edf7f1;color:var(--green);border-color:var(--green)}.flow-step.current{background:#fff7e8;color:var(--amber);border-color:var(--amber)}.managed-preview{white-space:pre-wrap;background:#f5f7f5;padding:11px;max-height:240px;overflow:auto;font:11px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace}.candidate-tracker{display:flex;align-items:flex-start;gap:10px;padding:11px 12px;margin-top:11px;border-left:3px solid var(--amber);background:#fffaf1}.candidate-tracker i{margin-top:2px;flex:none}.candidate-tracker strong{display:block}.candidate-tracker p{margin:2px 0 0;color:var(--muted);font-size:12px}.candidate-tracker.good{border-color:var(--green);background:#f1f8f4}.candidate-tracker.bad{border-color:var(--red);background:#fff7f6}.candidate-tracker.running i{animation:spin 1.2s linear infinite}.candidate-output{border-top:1px solid var(--line);margin-top:14px;padding-top:13px}.candidate-output h4{font-size:12px;margin:0 0 6px;text-transform:uppercase;color:var(--muted)}.candidate-output details{margin-top:9px}.candidate-output summary{cursor:pointer;font-weight:650}.next-action{margin-top:12px;padding:10px 12px;background:#f5f9fc;border-left:3px solid var(--blue)}.next-action strong{display:block}.next-action span{font-size:12px;color:var(--muted)}.gate{padding:9px 11px;margin-top:10px;border-left:3px solid var(--amber);background:#fffaf1}.gate.good{border-color:var(--green);background:#f1f8f4}.gate.bad{border-color:var(--red);background:#fff7f6}.candidate-test{margin-top:12px}.candidate-test textarea{min-height:76px}.submission{border:1px solid var(--line);padding:14px;margin:10px 0;background:#fff}.submission-head{display:flex;align-items:flex-start;gap:12px}.submission-head .status{margin-left:auto}.deliverables{display:grid;gap:7px;margin-top:12px}.deliverable{display:grid;grid-template-columns:22px minmax(0,1fr) 140px;align-items:center;gap:8px;padding:8px;border:1px solid var(--line);background:#fafbf9}.deliverable strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.deliverable small{color:var(--muted)}.source-picker{display:grid;grid-template-columns:1fr auto;gap:8px}.asset-picker{max-height:330px;overflow:auto;border:1px solid var(--line)}.asset-row{display:grid;grid-template-columns:24px minmax(0,1fr) 145px;gap:8px;align-items:center;padding:9px 10px;border-bottom:1px solid #edf0ee}.asset-row:last-child{border:0}.asset-row input{width:auto}.asset-row b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.asset-row small{color:var(--muted)}.asset-preview{margin-top:12px}.asset-preview video{max-height:280px}.asset-preview pre{max-height:220px;overflow:auto;white-space:pre-wrap;background:#f5f7f5;padding:10px;font-size:11px}@keyframes spin{to{transform:rotate(360deg)}}
    .current-round{background:#fff;border:1px solid var(--line);margin-bottom:24px}.current-round-head{display:flex;align-items:center;gap:12px;padding:15px 18px;border-bottom:1px solid var(--line)}.current-round-head h2{font-size:16px;margin:0}.current-round-head .meta{margin-left:auto}.workspace-grid{display:grid;grid-template-columns:minmax(360px,1.18fr) minmax(300px,.82fr);min-height:570px}.screen-stage{background:#eef1ee;padding:18px;border-right:1px solid var(--line);min-width:0}.player-toolbar{display:flex;align-items:center;gap:10px;margin-bottom:12px}.player-toolbar strong{font-size:13px}.view-switch{margin-left:auto;display:flex;border:1px solid #bfc9c3;border-radius:4px;overflow:hidden}.view-switch button{border:0;border-right:1px solid #bfc9c3;background:white;color:var(--muted);padding:6px 9px;font-size:12px}.view-switch button:last-child{border:0}.view-switch button.active{background:var(--ink);color:#fff}.video-frame{position:relative;margin:0 auto;width:min(100%,350px);aspect-ratio:9/16;background:#0d1210;display:grid;place-items:center;overflow:hidden;border-radius:4px}.video-frame video{width:100%;height:100%;max-height:none;object-fit:contain;border-radius:0}.player-badge{position:absolute;left:9px;top:9px;z-index:2;background:rgba(12,18,15,.78);color:#fff;padding:5px 7px;border-radius:3px;font-size:11px;pointer-events:none}.player-empty{padding:28px;text-align:center;color:#d9e1dc}.player-empty i{display:block;margin:0 auto 10px}.player-empty strong{display:block;color:#fff;margin-bottom:4px}.player-empty p{font-size:12px;margin:0 0 12px}.player-empty .secondary{background:#fff}.player-caption{display:flex;align-items:center;gap:10px;margin:10px auto 0;max-width:350px;min-width:0}.player-caption div{min-width:0}.player-caption strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.player-caption .actions{margin:0 0 0 auto;flex-wrap:nowrap}.player-caption .secondary{padding:6px 8px}.compare-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}.compare-grid>div{min-width:0}.compare-grid .video-frame{width:100%}.compare-grid .player-caption{display:block}.compare-grid .player-caption .actions{margin-top:8px}.round-status{padding:22px;display:flex;flex-direction:column;min-width:0}.round-status h3{font-size:19px;line-height:1.3;margin:0 0 6px}.round-kicker{font-size:11px;color:var(--muted);font-weight:700;text-transform:uppercase}.round-status .flow-steps{margin-top:20px}.round-status .next-action{margin-top:16px}.round-tabs{display:flex;gap:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:auto;background:#fafbf9}.round-tab{border:0;border-right:1px solid var(--line);background:transparent;color:var(--muted);padding:11px 15px;white-space:nowrap}.round-tab.active{background:#fff;color:var(--ink);font-weight:700;box-shadow:inset 0 -3px var(--green)}.tab-panel{display:none;padding:20px;min-height:180px}.tab-panel.active{display:block}.tab-panel-head{display:flex;align-items:flex-start;gap:14px;margin-bottom:14px}.tab-panel-head h3{margin:0;font-size:14px}.tab-panel-head p{margin:2px 0 0;color:var(--muted);font-size:12px}.tab-panel-head .actions{margin:0 0 0 auto}.compact-deliveries{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:8px}.compact-delivery{display:grid;grid-template-columns:22px minmax(0,1fr) auto;gap:8px;align-items:center;padding:9px 10px;border:1px solid var(--line);background:#fafbf9}.compact-delivery strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.compact-delivery small{color:var(--muted)}.history-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.history-grid h3{font-size:13px;margin:0 0 10px}.history-version{padding:11px 0;border-bottom:1px solid var(--line)}.history-version:first-child{padding-top:0}.history-version-head{display:flex;align-items:flex-start;gap:10px}.history-version-head .status{margin-left:auto}.baseline-strip{display:grid;grid-template-columns:120px minmax(0,1fr);gap:14px;align-items:start}.baseline-strip video{aspect-ratio:9/16;height:190px;object-fit:contain}.workspace-placeholder{display:grid;place-items:center;min-height:480px;text-align:center;color:var(--muted);padding:30px}.workspace-placeholder strong{display:block;color:var(--ink);margin-bottom:5px}.login{max-width:390px;margin:100px auto;background:white;border:1px solid var(--line);padding:28px;box-shadow:var(--shadow)}.login h1{font-size:21px;margin:0 0 8px}.login p{color:var(--muted)}.login .primary{margin-top:12px;width:100%;justify-content:center}.error{color:var(--red);margin-top:8px}.hidden{display:none!important}dialog{width:min(520px,calc(100vw - 32px));border:1px solid var(--line);border-radius:7px;padding:0;box-shadow:0 24px 70px rgba(20,29,25,.24);color:var(--ink)}dialog::backdrop{background:rgba(18,25,22,.46)}.dialog-head{padding:20px 22px 13px;border-bottom:1px solid var(--line);display:flex;align-items:center}.dialog-head h2{font-size:18px;margin:0}.dialog-close{margin-left:auto;border:0;background:transparent;font-size:21px;color:var(--muted)}.dialog-body{padding:18px 22px;display:grid;gap:14px}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:6px}.segments{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.segments label{border:1px solid var(--line);padding:8px;text-align:center;border-radius:4px;cursor:pointer}.segments input{position:absolute;opacity:0;width:1px}.segments label:has(input:checked){border-color:var(--green);background:var(--mint);color:var(--green);font-weight:700}.transport{grid-template-columns:1fr 1fr}.dialog-actions{padding:0 22px 20px;display:flex;justify-content:flex-end;gap:8px}.dialog-note{color:var(--muted);font-size:12px;margin:0}
    .prompt-preview{margin-top:12px}.prompt-preview details{border:1px solid var(--line);background:#fff}.prompt-preview summary{cursor:pointer;padding:10px 12px;font-weight:700}.full-prompt-preview{white-space:pre-wrap;margin:0;border-top:1px solid var(--line);background:#f5f7f5;padding:14px;max-height:560px;overflow:auto;font:12px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace}.handoff-steps{display:grid;gap:8px}.handoff-step{display:grid;grid-template-columns:28px minmax(0,1fr);gap:10px;align-items:start;padding:10px;border:1px solid var(--line);background:#fafbf9}.handoff-step b{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--mint);color:var(--green);font-size:12px}.handoff-step strong{display:block}.handoff-step span{display:block;color:var(--muted);font-size:12px;margin-top:2px}.commander-command{padding:12px;border:1px solid #b9c8bf;background:#f1f8f4;font:600 13px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.handoff-id{font:11px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--muted)}
    @media(max-width:900px){.workspace-grid{grid-template-columns:1fr}.screen-stage{border-right:0;border-bottom:1px solid var(--line)}.workspace-placeholder{min-height:260px}.history-grid{grid-template-columns:1fr}}
    @media(max-width:760px){header{padding:0 16px}.layout{grid-template-columns:minmax(0,1fr);width:100%}.layout>aside,.layout>main{min-width:0}aside{border-right:0;border-bottom:1px solid var(--line);padding:12px}.session-list{display:flex;overflow:auto}.session{min-width:210px}main{padding:22px 16px}.page-head p{overflow-wrap:anywhere}.progress{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.step:nth-child(2){border-right:0}.columns{grid-template-columns:1fr}.flow-steps{grid-template-columns:1fr 1fr}.page-head{display:block}.page-actions{margin:12px 0 0}.segments{grid-template-columns:1fr}.transport{grid-template-columns:1fr 1fr}.deliverable,.asset-row{grid-template-columns:22px minmax(0,1fr)}.deliverable select,.asset-row select{grid-column:2}.current-round-head{align-items:flex-start}.current-round-head .meta{margin-left:0}.workspace-grid{display:flex;flex-direction:column}.screen-stage{padding:12px}.round-status{padding:17px}.round-tabs{scrollbar-width:none}.tab-panel{padding:16px}.compare-grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:7px}.player-caption{display:block}.player-caption .actions{margin-top:7px}.baseline-strip{grid-template-columns:88px minmax(0,1fr)}.baseline-strip video{height:150px}}
  </style>
</head>
<body>
<div id="login" class="login hidden"><h1>校准控制台</h1><p>输入 Potato Gateway Bearer Token。</p><input id="token" type="password" autocomplete="current-password"><button class="primary" onclick="login()"><i data-lucide="log-in" width="16"></i>进入</button><div id="loginError" class="error"></div></div>
<div id="app" class="hidden"><header><i data-lucide="scan-eye" width="20"></i><span class="brand">Potato Calibration</span><span class="header-state" id="syncState">已连接</span></header><div class="layout"><aside><div class="agent-tabs" id="agentTabs"></div><div class="sidebar-actions"><button class="new-session" onclick="openCreateDialog()">+ 新建校准</button><label class="archive-toggle"><input id="showArchived" type="checkbox" onchange="toggleArchived(this.checked)">已归档</label></div><div class="session-list" id="sessions"></div></aside><main id="detail"><div class="empty">选择一个校准 Session</div></main></div></div>
<dialog id="createDialog"><div class="dialog-head"><h2>新建校准 Session</h2><button class="dialog-close" onclick="closeDialog('createDialog')" aria-label="关闭">×</button></div><div class="dialog-body"><div class="field"><label>校准入口</label><div class="segments transport"><label><input type="radio" name="sessionMode" value="existing" checked onchange="syncSessionMode()">历史交付</label><label><input type="radio" name="sessionMode" value="live" onchange="syncSessionMode()">现场生成</label></div></div><div class="field"><label>Agent</label><div class="segments" id="createAgents"></div></div><div class="field" id="transportField"><label>执行方式</label><div class="segments transport"><label><input type="radio" name="transport" value="hub" checked>Hub 自动执行</label><label><input type="radio" name="transport" value="manual">手动记录</label></div></div><div class="field"><label for="sessionGoal">校准目标</label><input id="sessionGoal" maxlength="4000" placeholder="例如：提升动态感并避免 PPT 式视频"></div><div class="field"><label for="sessionCriteria">验收标准</label><textarea id="sessionCriteria" placeholder="每行一条标准"></textarea></div><p class="dialog-note">历史交付不会调用清蒸土豆；现场生成会创建真实异步测试。</p><div id="createError" class="error"></div></div><div class="dialog-actions"><button class="secondary" onclick="closeDialog('createDialog')">取消</button><button class="primary" onclick="createSession()">创建 Session</button></div></dialog>
<dialog id="archiveDialog"><div class="dialog-head"><h2>归档校准 Session</h2><button class="dialog-close" onclick="closeDialog('archiveDialog')" aria-label="关闭">×</button></div><div class="dialog-body"><p>归档后默认从列表隐藏，校准记录与证据仍会保留。</p><div id="archiveError" class="error"></div></div><div class="dialog-actions"><button class="secondary" onclick="closeDialog('archiveDialog')">取消</button><button class="danger" onclick="archiveSession()">确认归档</button></div></dialog>
<dialog id="importDialog"><div class="dialog-head"><h2>选择历史交付包</h2><button class="dialog-close" onclick="closeDialog('importDialog')" aria-label="关闭">×</button></div><div class="dialog-body"><div class="field"><label for="assetSource">历史工作流或会话</label><div class="source-picker"><select id="assetSource" onchange="loadAssetSource()"></select><button class="secondary" onclick="loadAssetSources()">刷新</button></div></div><div id="assetPicker"><p class="meta">正在读取历史素材…</p></div><div id="assetPreview" class="asset-preview"></div><div id="importError" class="error"></div></div><div class="dialog-actions"><button class="secondary" onclick="closeDialog('importDialog')">取消</button><button class="primary" onclick="createImportedSubmission()">加入校准</button></div></dialog>
<dialog id="chatGptDialog"><div class="dialog-head"><h2>ChatGPT 校准任务已创建</h2><button class="dialog-close" onclick="closeDialog('chatGptDialog')" aria-label="关闭">×</button></div><div class="dialog-body"><div class="handoff-steps"><div class="handoff-step"><b>1</b><div><strong>证据任务已建立</strong><span id="chatGptTaskMeta">当前视频、你的反馈和独立评审已绑定。</span></div></div><div class="handoff-step"><b>2</b><div><strong>让土豆总指挥完成任务</strong><span>点击下方按钮后，在 ChatGPT 中发送已复制的这一句话。</span></div></div><div class="handoff-step"><b>3</b><div><strong>回到这里看结果</strong><span>页面会自动显示 ChatGPT 判断和新的 Prompt 草案。</span></div></div></div><div id="chatGptCommand" class="commander-command"></div><div id="chatGptTaskId" class="handoff-id"></div></div><div class="dialog-actions"><button class="secondary" onclick="copyChatGptTask(this)"><i data-lucide="copy" width="15"></i>仅复制</button><button class="primary" onclick="copyAndOpenChatGpt(this)"><i data-lucide="external-link" width="15"></i>复制并打开 ChatGPT</button></div></dialog>
<script>
const agents={creator:'清蒸土豆',researcher:'薯博士',critic:'酸辣土豆丝'};const assetRoles={storyboard:'分镜',sync_timeline:'同步时间轴',script:'脚本',evidence_manifest:'证据清单',subtitle:'字幕',audio:'音频',cover:'封面',primary_video:'主视频',other:'其他'};let agent='creator',selected='',token='',state={},showArchived=false,pollTimer=0,assetSource={},detailSignature='',refreshGeneration=0,activeCurrentTab='delivery',compareMode=false,analysisRequestBusy=false;const playbackRetries={};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function captureDetailUi(){const fields={},modules={},details={},media={};for(const el of document.querySelectorAll('#testInstruction,#feedbackText,[id^="candidateTest-"]')){if(el.id)fields[el.id]={value:el.value,start:el.selectionStart,end:el.selectionEnd,height:el.style.height}}document.querySelectorAll('.module').forEach(el=>modules[el.dataset.module]=el.classList.contains('open'));document.querySelectorAll('details[data-detail-key]').forEach(el=>details[el.dataset.detailKey]=el.open);document.querySelectorAll('video[data-asset-id]').forEach(el=>media[el.dataset.assetId]={time:el.currentTime,paused:el.paused,muted:el.muted,volume:el.volume,rate:el.playbackRate});const active=document.activeElement?.id||'';return{fields,modules,details,media,active,scrollX:window.scrollX,scrollY:window.scrollY}}
function restoreDetailUi(ui){if(!ui)return;document.querySelectorAll('.module').forEach(el=>{if(ui.modules[el.dataset.module]!==undefined)el.classList.toggle('open',ui.modules[el.dataset.module])});document.querySelectorAll('details[data-detail-key]').forEach(el=>{if(ui.details[el.dataset.detailKey]!==undefined)el.open=ui.details[el.dataset.detailKey]});for(const [id,saved] of Object.entries(ui.fields)){const el=document.querySelector(`#${id}`);if(!el)continue;el.value=saved.value;el.style.height=saved.height||'';if(id===ui.active){el.focus({preventScroll:true});if(saved.start!==null&&saved.end!==null)el.setSelectionRange(saved.start,saved.end)}}document.querySelectorAll('video[data-asset-id]').forEach(el=>{const saved=ui.media[el.dataset.assetId];if(!saved)return;el.muted=saved.muted;el.volume=saved.volume;el.playbackRate=saved.rate;const resume=()=>{if(Number.isFinite(saved.time))el.currentTime=Math.min(saved.time,Number.isFinite(el.duration)?el.duration:saved.time);if(!saved.paused)el.play().catch(()=>{})};if(el.readyState>=1)resume();else el.addEventListener('loadedmetadata',resume,{once:true})});window.scrollTo(ui.scrollX,ui.scrollY)}
function videoPlayer(assetId,label='成片'){const link=state.links?.[assetId];if(!assetId)return `<div class="workspace-placeholder"><div><i data-lucide="clapperboard" width="28"></i><strong>还没有候选成片</strong><span>从 Prompt 改进开始生成，进度会留在右侧。</span></div></div>`;if(!link?.available||!link.url)return `<div><div class="video-frame"><div class="player-empty"><i data-lucide="video-off" width="28"></i><strong>${esc(link?.title||`Asset #${assetId}`)}</strong><p>${esc(link?.playback_error||'素材暂时不可用')}</p><button class="secondary" onclick="retryPlayback(${assetId})"><i data-lucide="refresh-cw" width="15"></i>重新获取播放链接</button></div></div><div class="player-caption"><div><strong>${esc(label)}</strong><span class="meta">Asset #${assetId} · ${esc(link?.status||'unavailable')}</span></div></div></div>`;return `<div><div class="video-frame"><span class="player-badge" data-player-status="${assetId}">加载元数据</span><video data-asset-id="${assetId}" controls playsinline preload="metadata" src="${esc(link.url)}"></video><div class="player-empty hidden" data-player-error="${assetId}"><i data-lucide="circle-alert" width="28"></i><strong>成片暂时无法播放</strong><p>播放链接可能已过期，或素材服务暂时不可用。</p><button class="secondary" onclick="retryPlayback(${assetId})"><i data-lucide="refresh-cw" width="15"></i>重新获取播放链接</button></div></div><div class="player-caption"><div><strong>${esc(link.title||label)}</strong><span class="meta">${esc(label)} · Asset #${assetId}</span></div><div class="actions"><button class="secondary" title="重新获取播放链接" onclick="retryPlayback(${assetId})"><i data-lucide="refresh-cw" width="15"></i></button><a class="secondary" data-download-asset="${assetId}" title="下载成片" href="${esc(link.url)}" download><i data-lucide="download" width="15"></i></a></div></div></div>`}
function playerStatus(assetId,text){document.querySelectorAll(`[data-player-status="${assetId}"]`).forEach(el=>el.textContent=text)}
function showPlaybackError(assetId,message){playerStatus(assetId,'播放失败');document.querySelectorAll(`video[data-asset-id="${assetId}"]`).forEach(el=>el.classList.add('hidden'));document.querySelectorAll(`[data-player-error="${assetId}"]`).forEach(el=>{el.classList.remove('hidden');const p=el.querySelector('p');if(p)p.textContent=message})}
async function refreshPlaybackLink(assetId,manual=false){const key=`${selected}:${assetId}`;if(manual)playbackRetries[key]=0;playerStatus(assetId,'正在刷新链接');try{const link=await api(`/api/calibrations/${selected}/assets/${assetId}/link`);state.links[assetId]=link;if(!link.available||!link.url){showPlaybackError(assetId,link.playback_error||'素材暂时不可用');return}document.querySelectorAll(`video[data-asset-id="${assetId}"]`).forEach(video=>{video.classList.remove('hidden');const error=video.parentElement.querySelector(`[data-player-error="${assetId}"]`);error?.classList.add('hidden');video.src=link.url;video.load()});document.querySelectorAll(`[data-download-asset="${assetId}"]`).forEach(el=>el.href=link.url)}catch(e){showPlaybackError(assetId,e.message||'网络失败，请稍后重试')}}
function retryPlayback(assetId){refreshPlaybackLink(assetId,true)}
function bindPlayers(){document.querySelectorAll('video[data-asset-id]').forEach(video=>{if(video.dataset.playerBound)return;video.dataset.playerBound='1';const assetId=Number(video.dataset.assetId),key=`${selected}:${assetId}`;video.addEventListener('loadedmetadata',()=>{const duration=Number.isFinite(video.duration)?` · ${Math.round(video.duration)} 秒`:'';playerStatus(assetId,`可播放${duration}`);document.querySelectorAll(`[data-player-error="${assetId}"]`).forEach(el=>el.classList.add('hidden'));video.classList.remove('hidden')});video.addEventListener('waiting',()=>playerStatus(assetId,'缓冲中'));video.addEventListener('canplay',()=>playerStatus(assetId,'可播放'));video.addEventListener('error',()=>{if((playbackRetries[key]||0)<1){playbackRetries[key]=(playbackRetries[key]||0)+1;refreshPlaybackLink(assetId);return}showPlaybackError(assetId,'自动刷新后仍无法播放，请重新获取链接或下载成片。')})})}
function setCurrentTab(id){activeCurrentTab=id;document.querySelectorAll('.round-tab').forEach(el=>el.classList.toggle('active',el.dataset.tab===id));document.querySelectorAll('.tab-panel').forEach(el=>el.classList.toggle('active',el.dataset.panel===id));const panel=document.querySelector(`.tab-panel[data-panel="${id}"]`);if(panel&&window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches)gsap.fromTo(panel,{y:6,autoAlpha:0},{y:0,autoAlpha:1,duration:.22,ease:'power1.out',clearProps:'transform,opacity,visibility'})}
function toggleComparison(enabled){compareMode=enabled;renderDetail(false)}
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Authorization':`Bearer ${token}`,'Content-Type':'application/json',...(options.headers||{})}});if(r.status===401)throw new Error('unauthorized');const body=await r.json();if(!r.ok)throw new Error(body.detail||body.error||`HTTP ${r.status}`);return body}
function boot(){token=localStorage.getItem('potatoGatewayToken')||'';if(!token){showLogin();return}document.querySelector('#app').classList.remove('hidden');renderTabs();loadSessions()}
function showLogin(msg=''){document.querySelector('#app').classList.add('hidden');document.querySelector('#login').classList.remove('hidden');document.querySelector('#loginError').textContent=msg}
async function login(){token=document.querySelector('#token').value.trim();try{await api('/api/status');localStorage.setItem('potatoGatewayToken',token);document.querySelector('#login').classList.add('hidden');document.querySelector('#app').classList.remove('hidden');renderTabs();loadSessions()}catch(e){showLogin('Token 无效或 Gateway 不可用')}}
function renderTabs(){document.querySelector('#agentTabs').innerHTML=Object.entries(agents).map(([id,name])=>`<button class="${id===agent?'active':''}" onclick="setAgent('${id}')">${name.replace('土豆','')}</button>`).join('');document.querySelector('#createAgents').innerHTML=Object.entries(agents).map(([id,name])=>`<label><input type="radio" name="createAgent" value="${id}" ${id===agent?'checked':''}>${name}</label>`).join('');window.lucide?.createIcons()}
function setAgent(id){agent=id;selected='';detailSignature='';activeCurrentTab='delivery';compareMode=false;analysisRequestBusy=false;refreshGeneration++;clearTimeout(pollTimer);renderTabs();loadSessions()}
function toggleArchived(value){showArchived=value;selected='';detailSignature='';analysisRequestBusy=false;refreshGeneration++;loadSessions()}
function openCreateDialog(){document.querySelector('#createError').textContent='';document.querySelector('#sessionGoal').value='';document.querySelector('#sessionCriteria').value='';document.querySelector('input[name="sessionMode"][value="existing"]').checked=true;const choice=document.querySelector(`input[name="createAgent"][value="${agent}"]`);if(choice)choice.checked=true;syncSessionMode();document.querySelector('#createDialog').showModal()}
function syncSessionMode(){const historical=document.querySelector('input[name="sessionMode"]:checked')?.value==='existing',creator=document.querySelector('input[name="createAgent"][value="creator"]');document.querySelector('#transportField').classList.toggle('hidden',historical);document.querySelectorAll('input[name="createAgent"]').forEach(x=>x.disabled=historical&&x.value!=='creator');if(historical)creator.checked=true}
function closeDialog(id){document.querySelector(`#${id}`).close()}
async function createSession(){const button=document.querySelector('#createDialog .primary'),error=document.querySelector('#createError'),chosen=document.querySelector('input[name="createAgent"]:checked'),mode=document.querySelector('input[name="sessionMode"]:checked')?.value||'live',transport=mode==='existing'?'hub':document.querySelector('input[name="transport"]:checked')?.value||'hub',goal=document.querySelector('#sessionGoal').value.trim(),criteria=document.querySelector('#sessionCriteria').value.split('\n').map(x=>x.trim()).filter(Boolean);error.textContent='';if(!chosen||!goal){error.textContent='请选择 Agent，并填写校准目标。';return}button.disabled=true;button.textContent='创建中…';try{const created=await api('/api/calibrations',{method:'POST',body:JSON.stringify({client_request_id:`ui-session-${crypto.randomUUID()}`,agent_id:chosen.value,transport,goal,acceptance_criteria:criteria})});agent=chosen.value;selected=created.session_id;closeDialog('createDialog');renderTabs();await loadSessions();await refreshDetail();if(mode==='existing')await openImportDialog()}catch(e){error.textContent=e.message}finally{button.disabled=false;button.textContent='创建 Session'}}
function openArchiveDialog(){document.querySelector('#archiveError').textContent='';document.querySelector('#archiveDialog').showModal()}
async function archiveSession(){const button=document.querySelector('#archiveDialog .danger'),error=document.querySelector('#archiveError');button.disabled=true;button.textContent='归档中…';error.textContent='';try{await api(`/api/calibrations/${selected}`,{method:'DELETE'});closeDialog('archiveDialog');selected='';await loadSessions()}catch(e){error.textContent=e.message}finally{button.disabled=false;button.textContent='确认归档'}}
async function restoreSession(){try{await api(`/api/calibrations/${selected}/restore`,{method:'POST',body:'{}'});await loadSessions();await refreshDetail()}catch(e){alert(e.message)}}
async function loadSessions(){try{const data=await api(`/api/agents/${agent}/calibrations?limit=100`),visible=data.sessions.filter(s=>showArchived||s.state!=='closed');document.querySelector('#sessions').innerHTML=visible.map(s=>`<button class="session ${s.session_id===selected?'active':''}" onclick="selectSession('${esc(s.session_id)}')"><strong>${esc(s.goal)}</strong><small>${new Date(s.updated_at).toLocaleString()} · ${s.state==='closed'?'已归档':esc(s.state)}</small></button>`).join('')||'<div class="empty">暂无 Session</div>';if(!selected&&visible[0])selectSession(visible[0].session_id);if(!visible.length)document.querySelector('#detail').innerHTML='<div class="empty">点击“新建校准”开始</div>'}catch(e){if(e.message==='unauthorized')showLogin('登录已失效');else document.querySelector('#sessions').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function selectSession(id){if(id!==selected){selected=id;detailSignature='';activeCurrentTab='delivery';compareMode=false;analysisRequestBusy=false;refreshGeneration++}loadSessions();await refreshDetail(true)}
function candidateExecutions(){return(state.execs||[]).filter(x=>x.prompt_version_id)}
function candidateExecutionIds(){return new Set(candidateExecutions().map(x=>x.execution_id))}
function baselineSubmissions(){const ids=candidateExecutionIds();return(state.submissions||[]).filter(x=>!x.execution_id||!ids.has(x.execution_id))}
function candidateSubmissionIds(){const ids=candidateExecutionIds();return new Set((state.submissions||[]).filter(x=>ids.has(x.execution_id)).map(x=>x.submission_id))}
function baselineReviews(){const ids=candidateSubmissionIds();return(state.reviews||[]).filter(x=>!x.submission_id||!ids.has(x.submission_id))}
function latestAdvisorySource(){const reviews=(state.reviews||[]).slice().sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at));for(const review of reviews){if(review.status!=='completed'||!review.submission_id)continue;const submission=(state.submissions||[]).find(x=>x.submission_id===review.submission_id);if(submission)return{submission,review}}return null}
function latestAdvisory(){const source=latestAdvisorySource();if(!source)return null;return(state.advisories||[]).filter(x=>x.submission_id===source.submission.submission_id&&x.review_id===source.review.review_id).slice().sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at))[0]||null}
function candidateContext(version){const attempts=candidateExecutions().filter(x=>x.prompt_version_id===version.prompt_version_id),execution=attempts[0],submission=execution&&(state.submissions||[]).find(x=>x.execution_id===execution.execution_id),review=submission&&(state.reviews||[]).find(x=>x.submission_id===submission.submission_id);return{attempts,execution,submission,review}}
function hasActiveWork(){if((state.execs||[]).some(x=>['queued','running'].includes(x.status))||(state.reviews||[]).some(x=>['queued','preparing','reviewing'].includes(x.status))||(state.advisories||[]).some(x=>x.status==='pending'))return true;return(state.prompts||[]).some(p=>{if(p.status!=='testing')return false;const c=candidateContext(p);return !c.execution||(c.execution.status==='completed'&&c.execution.asset_ids.length>0&&!c.submission)})}
async function refreshDetail(force=false){if(!selected)return;clearTimeout(pollTimer);const sessionId=selected,generation=++refreshGeneration;try{const [session,execs,submissions,reviews,prompts,advisories]=await Promise.all([api(`/api/calibrations/${sessionId}`),api(`/api/calibrations/${sessionId}/executions`),api(`/api/calibrations/${sessionId}/submissions`),api(`/api/calibrations/${sessionId}/reviews`),api(`/api/agents/${agent}/prompt-versions?limit=20`),api(`/api/calibration-advisories?session_id=${encodeURIComponent(sessionId)}&limit=20`)]);if(sessionId!==selected||generation!==refreshGeneration)return;const nextState={session,execs:execs.executions,submissions:submissions.submissions,reviews:reviews.reviews,prompts:prompts.versions,advisories:advisories.advisories},nextSignature=JSON.stringify(nextState),firstRender=!detailSignature;state=nextState;if(force||nextSignature!==detailSignature){await renderDetail(firstRender);if(sessionId!==selected||generation!==refreshGeneration)return;detailSignature=nextSignature}document.querySelector('#syncState').textContent='已连接';if(hasActiveWork())pollTimer=setTimeout(()=>refreshDetail(false),5000)}catch(e){if(sessionId!==selected||generation!==refreshGeneration)return;document.querySelector('#syncState').textContent='连接暂时中断';if(hasActiveWork())pollTimer=setTimeout(()=>refreshDetail(false),5000)}}
function progressState(){const candidate=currentPromptVersion();if(candidate){const c=candidateContext(candidate),hard=c.review?.status==='completed'&&(c.review.report?.hard_errors||[]).length>0;if(c.review?.status==='completed'&&c.review.report?.verdict==='revise'){const advisory=latestAdvisory();return{labels:['候选成片','我的反馈','独立评审','ChatGPT 分析','新 Prompt'],current:advisory?.status==='completed'?6:4}}const labels=['校准输入','Prompt 草案','隔离复测','独立评审','人工激活'];let current=2;if(candidate.status==='active')current=6;else if(!c.execution)current=2;else if(['queued','running','failed'].includes(c.execution.status)||!c.submission&&agent==='creator')current=3;else if(agent==='creator'&&(!c.review||c.review.status!=='completed'))current=4;else if(hard)current=5;else current=5;return{labels,current}}const sub=baselineSubmissions(),rv=baselineReviews(),labels=['校准输入','原始交付','独立评审','生成草案'];let current=1;if(rv.some(x=>x.status==='completed'))current=4;else if(rv.some(x=>['queued','preparing','reviewing'].includes(x.status)))current=3;else if(sub.length)current=2;return{labels,current}}
function formatDuration(ms){const total=Math.max(0,Math.floor(ms/1000)),minutes=Math.floor(total/60),seconds=total%60;return minutes?`${minutes} 分 ${seconds} 秒`:`${seconds} 秒`}
function updateElapsed(){document.querySelectorAll('[data-elapsed-from]').forEach(el=>{const start=Date.parse(el.dataset.elapsedFrom);if(Number.isFinite(start))el.textContent=`已运行 ${formatDuration(Date.now()-start)}`})}
function currentPromptVersion(){const versions=(state.prompts||[]).filter(p=>p.calibration_session_id===selected).slice().sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at));return versions.find(p=>p.status!=='retired')||versions[0]||null}
function roundGate(version,context){if(!version)return{steps:[false,false,false,false,false],current:0,status:`<div class="candidate-tracker"><i data-lucide="circle-dashed" width="17"></i><div><strong>等待第一份 Prompt 草案</strong><p>在 Prompt 改进中记录可选反馈，然后生成草案。</p></div></div>`,action:`<div class="next-action"><strong>下一步：生成 Prompt 草案</strong><span>系统会综合校准目标、交付与评审生成受控改进规则。</span></div><div class="actions"><button class="primary" onclick="setCurrentTab('prompt')"><i data-lucide="wand-sparkles" width="16"></i>进入 Prompt 改进</button></div>`};const ex=context.execution,sub=context.submission,review=context.review,testDone=ex?.status==='completed',hard=review?.status==='completed'&&(review.report?.hard_errors||[]).length>0,failed=ex?.status==='failed',steps=version.status==='active'?[true,true,true,true,true]:[true,testDone,agent==='creator'?!!sub:testDone,agent==='creator'?review?.status==='completed':testDone,false];let current=1,statusHtml='',action='';if(version.status==='active'){current=5;statusHtml='<div class="candidate-tracker good"><i data-lucide="circle-check" width="17"></i><div><strong>这个版本已经正式生效</strong><p>本轮闭环已完成，旧版本仍可回滚。</p></div></div>'}else if(!ex){statusHtml='<div class="candidate-tracker"><i data-lucide="circle-dashed" width="17"></i><div><strong>草案已生成，尚未开始复测</strong><p>正式 Prompt 没有改变；复测会使用隔离 Profile。</p></div></div>';action=candidateTestForm(version)}else if(ex.status==='queued'){current=1;statusHtml='<div class="candidate-tracker running"><i data-lucide="loader-circle" width="17"></i><div><strong>隔离复测已排队</strong><p>等待清蒸土豆 Runner 领取，不需要人工批准。</p></div></div>'}else if(ex.status==='running'){current=1;statusHtml=`<div class="candidate-tracker running"><i data-lucide="loader-circle" width="17"></i><div><strong>清蒸土豆正在执行隔离复测</strong><p><span data-elapsed-from="${esc(ex.created_at)}"></span>，页面会在后台同步。</p></div></div>`}else if(failed){current=1;statusHtml=`<div class="candidate-tracker bad"><i data-lucide="circle-x" width="17"></i><div><strong>隔离复测失败</strong><p>${esc(executionErrorMessage(ex.error)||'执行未完成')}</p></div></div>`;action=`<div class="next-action"><strong>下一步：重新运行</strong><span>失败记录会保留，新任务仍使用同一候选 Prompt。</span></div>${candidateTestForm(version,true)}`}else if(agent==='creator'&&!sub){current=2;statusHtml='<div class="candidate-tracker running"><i data-lucide="loader-circle" width="17"></i><div><strong>成片已返回，正在登记交付包</strong><p>系统正在核验托管素材并生成 Submission。</p></div></div>'}else if(agent==='creator'&&sub&&!review){current=3;statusHtml='<div class="candidate-tracker good"><i data-lucide="video" width="17"></i><div><strong>候选成片已就绪</strong><p>你可以先播放检查，再手动交给酸辣土豆丝评审。</p></div></div>';action=`<div class="next-action"><strong>下一步：独立评审</strong><span>这是人工触发的门禁，不会自动返工。</span></div><div class="actions"><button class="primary" onclick="createSubmissionReview('${sub.submission_id}')"><i data-lucide="scan-eye" width="16"></i>交给酸辣土豆丝评审</button></div>`}else if(agent==='creator'&&review&&['queued','preparing','reviewing'].includes(review.status)){current=3;statusHtml='<div class="candidate-tracker running"><i data-lucide="loader-circle" width="17"></i><div><strong>酸辣土豆丝正在独立评审</strong><p>评分、硬错误和证据完成后会出现在评审 Tab。</p></div></div>'}else if(hard){current=4;statusHtml='<div class="candidate-tracker bad"><i data-lucide="shield-x" width="17"></i><div><strong>评审发现硬错误</strong><p>这个候选不能激活，请补充反馈并生成下一版。</p></div></div>';action=`<div class="next-action"><strong>下一步：继续改进 Prompt</strong><span>硬错误不会被自动忽略。</span></div><div class="actions"><button class="primary" onclick="setCurrentTab('prompt')"><i data-lucide="file-pen-line" width="16"></i>记录反馈并生成下一版</button></div>`}else{current=4;statusHtml='<div class="candidate-tracker good"><i data-lucide="badge-check" width="17"></i><div><strong>隔离复测门禁已通过</strong><p>现在只差你的人工确认，系统不会自行发布。</p></div></div>';action=`<div class="next-action"><strong>下一步：人工激活</strong><span>确认后，此候选才会成为正式 Prompt。</span></div><div class="actions"><button class="primary" onclick="activateCandidate('${version.prompt_version_id}','${version.content_sha256}')"><i data-lucide="badge-check" width="16"></i>确认激活此 Prompt</button></div>`}return{steps,current,status:statusHtml,action}}
const successfulRoundGate=roundGate;
roundGate=function(version,context){const advisory=latestAdvisory(),review=context?.review,submission=context?.submission,hard=review?.status==='completed'&&(review.report?.hard_errors||[]).length>0;if(advisory?.status==='pending')return{steps:[true,true,true,false,false],current:3,status:`<div class="candidate-tracker running"><i data-lucide="message-circle-more" width="17"></i><div><strong>ChatGPT 校准任务待处理</strong><p>${esc(advisory.advisory_id)} 已建立；页面正在等待土豆总指挥写回结果。</p></div></div>`,action:`<div class="next-action"><strong>下一步：在土豆总指挥发送一句话</strong><span>${esc(commanderTaskText(advisory))}</span></div><div class="actions"><button class="primary" onclick="showChatGptHandoff('${advisory.advisory_id}')"><i data-lucide="external-link" width="16"></i>打开任务交接</button><button class="secondary" onclick="refreshDetail(true)"><i data-lucide="refresh-cw" width="16"></i>刷新结果</button></div>`};if(version&&submission&&review?.status==='failed')return{steps:[true,true,true,false,false],current:3,status:'<div class="candidate-tracker bad"><i data-lucide="file-warning" width="17"></i><div><strong>评审报告结构校验失败</strong><p>视频和证据没有丢失，也不代表成片通过或不通过。</p></div></div>',action:`<div class="next-action"><strong>你可以任选下一步</strong><span>重试会重新生成独立报告；也可以先按你的主观判断继续改 Prompt，失败报告不会被采用。</span></div><div class="actions"><button class="primary" onclick="createSubmissionReview('${submission.submission_id}',true)"><i data-lucide="rotate-cw" width="16"></i>重试独立评审</button><button class="secondary" onclick="setCurrentTab('prompt')"><i data-lucide="file-pen-line" width="16"></i>先记录我的反馈</button></div>`};if(version&&submission&&review?.status==='completed'&&review.report?.verdict==='revise'&&!hard)return{steps:[true,true,true,false,false],current:3,status:`<div class="candidate-tracker"><i data-lucide="file-pen-line" width="17"></i><div><strong>反馈和独立评审都已就绪</strong><p>酸辣土豆丝评分 ${esc(review.report?.total_score??'--')}，可以创建本轮 ChatGPT 校准任务。</p></div></div>`,action:`<div class="next-action"><strong>推荐下一步：创建 ChatGPT 校准任务</strong><span>任务会绑定当前视频、交付件、你的反馈和酸辣土豆丝证据。</span></div><div class="actions"><button class="primary" onclick="createAdvisory()" ${analysisRequestBusy?'disabled':''}><i data-lucide="messages-square" width="16"></i>${analysisRequestBusy?'正在创建…':'创建 ChatGPT 校准任务'}</button><button class="secondary" onclick="activateCandidate('${version.prompt_version_id}','${version.content_sha256}')"><i data-lucide="badge-check" width="16"></i>仍然接受此版本</button></div>`};return successfulRoundGate(version,context)}
function currentAssetId(context){if(context?.submission)return context.submission.primary_video.asset_id;return(context?.execution?.asset_ids||[]).find(id=>state.links?.[id]?.asset_type==='video')||0}
function renderCurrentRound(){const version=currentPromptVersion(),context=version?candidateContext(version):{attempts:[],execution:null,submission:null,review:null},gate=roundGate(version,context),assetId=currentAssetId(context),baseline=baselineSubmissions()[0],baselineId=baseline?.primary_video.asset_id||0,revising=context.review?.status==='completed'&&context.review.report?.verdict==='revise',labels=revising?['候选成片','保存反馈','独立评审','ChatGPT 分析','新 Prompt']:['生成草案','执行复测','检查产物','独立评审','人工激活'],roundTitle=context.submission?.primary_video?.title||version?.change_summary||'建立本轮校准输入',roundMeta=version?`${version.content_sha256.slice(0,12)} · ${context.attempts.length} 次复测`:'尚未生成候选版本';const player=agent==='creator'?`<div class="player-toolbar"><strong>${compareMode?'新旧成片对比':'最新候选成片'}</strong>${baselineId&&assetId?`<div class="view-switch"><button class="${compareMode?'':'active'}" onclick="toggleComparison(false)">候选</button><button class="${compareMode?'active':''}" onclick="toggleComparison(true)">新旧对比</button></div>`:''}</div>${compareMode&&baselineId&&assetId?`<div class="compare-grid">${videoPlayer(baselineId,'原片')}${videoPlayer(assetId,'候选')}</div>`:videoPlayer(assetId,'候选成片')}`:`<div class="workspace-placeholder"><div><i data-lucide="messages-square" width="28"></i><strong>本轮 Agent 输出</strong><span>文字结果与执行记录可在下方 Tab 查看。</span></div></div>`;const tabs=[['delivery','成片与交付'],['review','评审与证据'],['prompt','Prompt 改进'],['execution','执行记录']];return `<section class="current-round"><div class="current-round-head"><i data-lucide="focus" width="18"></i><h2>当前校准轮次</h2><div class="meta">${esc(roundMeta)}</div></div><div class="workspace-grid"><div class="screen-stage">${player}</div><div class="round-status"><span class="round-kicker">Current round</span><h3>${esc(roundTitle)}</h3><div class="meta">${version?esc(version.status):'等待开始'}${context.review?.report?.total_score!==undefined?` · 评分 ${esc(context.review.report.total_score)}`:''}</div><div class="flow-steps">${labels.map((x,i)=>`<div class="flow-step ${gate.steps[i]?'done':i===gate.current?'current':''}">${x}</div>`).join('')}</div>${gate.status}${gate.action||''}</div></div><nav class="round-tabs" aria-label="当前轮次视图">${tabs.map(([id,label])=>`<button class="round-tab ${activeCurrentTab===id?'active':''}" data-tab="${id}" onclick="setCurrentTab('${id}')">${label}</button>`).join('')}</nav><div class="tab-panel ${activeCurrentTab==='delivery'?'active':''}" data-panel="delivery">${renderRoundDelivery(context)}</div><div class="tab-panel ${activeCurrentTab==='review'?'active':''}" data-panel="review">${renderRoundReview(context)}</div><div class="tab-panel ${activeCurrentTab==='prompt'?'active':''}" data-panel="prompt">${renderRoundPrompt(version)}</div><div class="tab-panel ${activeCurrentTab==='execution'?'active':''}" data-panel="execution">${renderRoundExecution(context)}</div></section>`}
function renderRoundDelivery(context){const sub=context.submission;if(!sub)return `<div class="tab-panel-head"><div><h3>本轮交付</h3><p>${context.execution?.status==='completed'?'正在把已登记素材整理为 Submission。':'完成隔离复测后，成片和配套交付件会统一出现在这里。'}</p></div></div>`;return `<div class="tab-panel-head"><div><h3>${esc(sub.primary_video.title)}</h3><p>${esc(sub.submission_id)} · ${esc(sub.status)}</p></div></div><div class="compact-deliveries">${sub.support_assets.map(x=>`<div><div class="compact-delivery"><i data-lucide="file" width="16"></i><div><strong>${esc(x.title)}</strong><small>Asset #${x.asset_id}</small></div><span>${esc(assetRoles[x.role]||x.role)}</span></div>${x.text_preview?`<details data-detail-key="round:${sub.submission_id}:${x.asset_id}"><summary>查看内容摘要</summary><pre class="reply">${esc(x.text_preview)}</pre></details>`:''}</div>`).join('')||'<p class="meta">本轮只有主视频，没有配套交付件。</p>'}</div>`}
function renderRoundReview(context){const review=context.review;if(!context.submission)return '<p class="meta">候选 Submission 完成后，才能发起独立评审。</p>';if(!review)return `<div class="tab-panel-head"><div><h3>尚未发起独立评审</h3><p>酸辣土豆丝只负责评分和证据标注，不会修改 Prompt 或自动返工。</p></div><div class="actions"><button class="primary" onclick="createSubmissionReview('${context.submission.submission_id}')"><i data-lucide="scan-eye" width="16"></i>发起评审</button></div></div>`;const failed=review.status==='failed'?`<div class="actions"><button class="primary" onclick="createSubmissionReview('${context.submission.submission_id}',true)"><i data-lucide="rotate-cw" width="16"></i>重试评审</button><button class="secondary" onclick="setCurrentTab('prompt')"><i data-lucide="file-pen-line" width="16"></i>先记录我的反馈</button></div>`:'';return `${reviewBody(review)}${failed}${review.status==='completed'?`<div class="actions"><button class="secondary" onclick="loadCandidateEvidence('${review.review_id}','currentEvidence-${review.review_id}')"><i data-lucide="images" width="16"></i>加载关键帧与 Contact Sheet</button></div><div id="currentEvidence-${review.review_id}"></div>`:''}`}
function advisoryAnalysisHtml(advisory){const a=advisory.analysis;if(!a)return'';return `<div class="candidate-output"><h4>ChatGPT 综合判断</h4><h3>${esc(a.executive_summary)}</h3><div class="gate"><strong>对你意图的理解</strong><br>${esc(a.user_intent)}</div>${a.strengths.length?`<details data-detail-key="advisor-strengths:${advisory.advisory_id}"><summary>值得保留的部分</summary><ul>${a.strengths.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}<h4>关键诊断</h4>${a.findings.map(x=>`<div class="${x.severity==='high'?'hard':'style'}"><strong>${esc(x.category)} · ${esc(x.severity)}</strong><br>${esc(x.diagnosis)}<div class="meta">根因：${esc(x.root_cause)}${x.time_ranges.length?` · ${esc(x.time_ranges.join('、'))}`:''}${x.evidence_asset_ids.length?` · 证据 ${esc(x.evidence_asset_ids.join(', '))}`:''}</div></div>`).join('')}<h4>下一步优化顺序</h4>${a.priority_actions.slice().sort((x,y)=>x.priority-y.priority).map(x=>`<div class="next-action"><strong>P${x.priority} · ${esc(x.action)}</strong><span>${esc(x.rationale)}${x.evidence_asset_ids.length?` · 证据 ${esc(x.evidence_asset_ids.join(', '))}`:''}</span></div>`).join('')}<details open data-detail-key="advisor-patch:${advisory.advisory_id}"><summary>ChatGPT 提炼的 Prompt patch</summary><pre class="managed-preview">${esc(a.prompt_patch.map(x=>`- ${x}`).join('\n'))}</pre></details>${a.stale_rules_to_drop.length?`<details data-detail-key="advisor-stale:${advisory.advisory_id}"><summary>不再沿用的旧规则</summary><pre class="managed-preview">${esc(a.stale_rules_to_drop.map(x=>`- ${x}`).join('\n'))}</pre></details>`:''}<details data-detail-key="advisor-retest:${advisory.advisory_id}"><summary>隔离复测任务与验收标准</summary><pre class="managed-preview">${esc(a.retest_instruction)}\n\n${esc(a.acceptance_criteria.map(x=>`- ${x}`).join('\n'))}</pre></details><div class="actions"><button class="primary" onclick="goToCandidateTest('${advisory.prompt_version_id}')"><i data-lucide="flask-conical" width="15"></i>使用 ChatGPT 草案复测</button></div></div>`}
function chatGptAdvisoryPanel(){const source=latestAdvisorySource(),advisory=latestAdvisory();if(!source)return'<div class="candidate-intro"><h3>ChatGPT 深度校准</h3><div class="generation-notice"><i data-lucide="scan-eye" width="17"></i><div><strong>等待本轮视频评审</strong><span>需要先有候选成片和酸辣土豆丝的已完成评审，才能建立 ChatGPT 任务。</span></div></div></div>';if(advisory?.status==='pending')return`<div class="candidate-intro"><div class="tab-panel-head"><div><h3>ChatGPT 校准任务待处理</h3><p>${esc(advisory.advisory_id)} · 页面会自动同步写回结果</p></div><span class="status">等待 ChatGPT</span></div><div class="generation-notice running"><i data-lucide="message-circle-more" width="17"></i><div><strong>证据任务已经创建</strong><span>在土豆总指挥发送下面这句话即可。</span></div></div><div class="next-action"><strong>发送给土豆总指挥</strong><span>${esc(commanderTaskText(advisory))}</span></div><div class="actions"><button class="primary" onclick="showChatGptHandoff('${advisory.advisory_id}')"><i data-lucide="external-link" width="15"></i>复制并打开 ChatGPT</button><button class="secondary" onclick="refreshDetail(true)"><i data-lucide="refresh-cw" width="15"></i>刷新结果</button></div></div>`;if(advisory?.status==='completed')return`<div class="candidate-intro"><div class="tab-panel-head"><div><h3>ChatGPT 深度校准已完成</h3><p>${new Date(advisory.completed_at).toLocaleString()} · ${esc(advisory.advisory_id)}</p></div><span class="status">已写回</span></div>${advisoryAnalysisHtml(advisory)}<div class="actions"><button class="secondary" onclick="createAdvisory()" ${analysisRequestBusy?'disabled':''}><i data-lucide="refresh-cw" width="15"></i>基于最新反馈再分析</button></div></div>`;return`<div class="candidate-intro"><h3>创建本轮 ChatGPT 校准任务</h3><p class="meta">任务会绑定当前视频与交付件、你的主观反馈、酸辣土豆丝报告和视觉证据。ChatGPT 写回后会自动生成下一版 Prompt 草案。</p><div class="generation-notice good"><i data-lucide="package-check" width="17"></i><div><strong>本轮证据已就绪</strong><span>${esc(source.submission.submission_id)} · 评审 ${esc(source.review.review_id)}${source.review.report?.total_score!==undefined?` · ${esc(source.review.report.total_score)} 分`:''}</span></div></div><div class="actions"><button class="primary" onclick="createAdvisory()" ${analysisRequestBusy?'disabled':''}><i data-lucide="messages-square" width="16"></i>${analysisRequestBusy?'正在创建…':'创建 ChatGPT 校准任务'}</button></div></div>`}
function renderRoundPrompt(version,context){context=context||(version?candidateContext(version):{});const isChatGpt=version?.managed_addendum?.includes('# ChatGPT calibration patch'),legacy=version&&!isChatGpt?'<div class="gate bad"><strong>当前草案不是 ChatGPT 分析结果</strong><br><span>这是旧式 Gateway 规则拼接草案，不建议继续复测。请以下方 ChatGPT 深度校准结果生成的新候选为准。</span></div>':'',preview=version?`<div class="actions"><button class="secondary" onclick="loadPromptDraft('${version.prompt_version_id}')"><i data-lucide="file-search" width="16"></i>查看完整 Prompt 草案</button></div><div id="promptDraftPreview" class="prompt-preview"></div>`:'';return `<div class="tab-panel-head"><div><h3>校准判断与 Prompt 改进</h3><p>你的反馈、酸辣土豆丝证据和 ChatGPT 综合判断分别保留，不再混成一份历史规则列表。</p></div></div>${renderFeedback()}${chatGptAdvisoryPanel()}${legacy}${isChatGpt&&version?.managed_addendum?`<details data-detail-key="prompt:${version.prompt_version_id}" open><summary>当前 ChatGPT Prompt patch</summary><pre class="managed-preview">${esc(version.managed_addendum)}</pre></details>`:''}${preview}`}
function renderRoundExecution(context){if(!context.execution)return '<p class="meta">尚未开始隔离复测。启动后，要求、真实回复、耗时和失败原因会显示在这里。</p>';return candidateExecutionRecord(context)}
function renderBaselineArea(){const subs=renderSubmissions(),reviews=renderReviews();return `<div class="history-grid"><div><h3>基准交付</h3>${subs}</div><div><h3>原始评审</h3>${reviews}<div id="evidenceArea"><p class="meta">完成原始评审后，可按需查看关键帧与 Contact Sheet。</p></div></div></div>`}
function renderHistoryArea(){const current=currentPromptVersion(),versions=(state.prompts||[]).filter(p=>(p.calibration_session_id===selected||p.status==='active')&&p.prompt_version_id!==current?.prompt_version_id),currentExecution=current?candidateContext(current).execution:null,executions=(state.execs||[]).filter(ex=>ex.execution_id!==currentExecution?.execution_id);return `<div class="history-grid"><div><h3>Prompt 版本历史</h3>${versions.map(p=>`<div class="history-version"><div class="history-version-head"><div><strong>${esc(p.change_summary)}</strong><div class="meta">${p.content_sha256.slice(0,12)} · ${new Date(p.created_at).toLocaleString()}</div></div><span class="status ${p.status==='retired'?'closed':''}">${esc(p.status)}</span></div>${p.managed_addendum?`<details data-detail-key="history-prompt:${p.prompt_version_id}"><summary>查看改进规则</summary><pre class="managed-preview">${esc(p.managed_addendum)}</pre></details>`:''}${p.status==='retired'?`<div class="actions"><button class="secondary" onclick="rollbackCandidate('${p.prompt_version_id}','${p.content_sha256}')"><i data-lucide="undo-2" width="15"></i>回滚</button></div>`:''}</div>`).join('')||'<p class="meta">暂无旧 Prompt 版本。</p>'}</div><div><h3>旧执行记录</h3>${executions.map(ex=>`<div class="execution"><strong>${esc(ex.instruction)}</strong><div class="meta">${esc(ex.status)} · ${new Date(ex.created_at).toLocaleString()} · ${ex.asset_ids.length} 个素材</div>${ex.response?`<details data-detail-key="history-execution:${ex.execution_id}"><summary>查看真实回复</summary><pre class="reply">${esc(ex.response)}</pre></details>`:''}${ex.error?`<div class="error">${esc(executionErrorMessage(ex.error))}</div>`:''}</div>`).join('')||'<p class="meta">暂无旧执行记录。</p>'}</div></div>`}
async function renderDetail(animate=false){const s=state.session,progress=progressState(),links={};const ids=new Set(state.execs.flatMap(ex=>ex.asset_ids));for(const sub of state.submissions){ids.add(sub.primary_video.asset_id);sub.support_assets.forEach(x=>ids.add(x.asset_id))}for(const id of ids){try{links[id]=await api(`/api/calibrations/${selected}/assets/${id}/link`)}catch{}}state.links=links;const ui=captureDetailUi(),baseSubs=baselineSubmissions(),baseReviews=baselineReviews();document.querySelector('#detail').innerHTML=`
<div class="page-head"><div><h1>${esc(s.goal)}</h1><p>${agents[s.agent_id]} · ${esc(s.session_id)} · ${esc(s.transport)}</p></div><div class="page-actions"><button class="refresh" onclick="refreshDetail(true)"><i data-lucide="refresh-cw" width="15"></i></button>${s.state==='closed'?`<button class="secondary" onclick="restoreSession()">恢复</button>`:`<button class="danger" onclick="openArchiveDialog()">归档</button>`}<span class="status ${s.state==='closed'?'closed':''}">${s.state==='closed'?'已归档':esc(s.state)}</span></div></div>
<div class="progress" style="--steps:${progress.labels.length}">${progress.labels.map((x,i)=>`<div class="step ${i+1<progress.current?'done':i+1===progress.current?'current':''}"><b>${x}</b><span>${i+1<progress.current?'已完成':i+1===progress.current?'当前阶段':'待处理'}</span></div>`).join('')}</div>
${renderCurrentRound()}
${!currentPromptVersion()&&s.transport==='hub'?module('execution','现场基准测试',(state.execs||[]).filter(x=>!x.prompt_version_id).length,renderExecutions(),true):''}
${module('baseline','基准交付与原始评审',baseSubs.length+baseReviews.length,renderBaselineArea())}
${module('history','历史轮次与执行记录',(state.execs||[]).length+(state.prompts||[]).length,renderHistoryArea())}`;bindModules();bindPlayers();restoreDetailUi(ui);window.lucide?.createIcons();updateElapsed();if(animate)animateIn()}
function module(id,title,count,body,open=false){return `<section class="module ${open?'open':''}" data-module="${id}"><button class="module-head"><i data-lucide="${({baseline:'columns-2',history:'history',submission:'package-open',execution:'film',review:'badge-check',evidence:'images',feedback:'messages-square',prompt:'file-pen-line'})[id]}" width="18"></i><strong>${title}</strong><span class="count">${count}</span><i class="chevron" data-lucide="chevron-down" width="17"></i></button><div class="module-body">${body}</div></section>`}
function renderSubmissions(){const submissions=baselineSubmissions(),add=state.session.state==='calibrating'?`<div class="actions"><button class="secondary" onclick="openImportDialog()"><i data-lucide="package-plus" width="16"></i>导入历史交付</button></div>`:'';if(!submissions.length)return `${add}<p class="meta">还没有原始交付版本。可导入历史包，或在基准现场测试中运行一次新任务。</p>`;return add+submissions.map((sub,index)=>{const review=baselineReviews().find(r=>r.submission_id===sub.submission_id),link=state.links[sub.primary_video.asset_id],parent=sub.parent_submission_id?` · 上一版 ${esc(sub.parent_submission_id.slice(0,12))}`:'';return `<article class="submission"><div class="submission-head"><div><h3>${esc(sub.primary_video.title)}</h3><div class="meta">版本 ${submissions.length-index} · ${sub.source_type==='existing_assets'?'历史交付':'现场生成'} · ${esc(sub.submission_id)}${parent}</div></div><span class="status">${esc(sub.status)}</span></div>${link?.available&&link.url?`<video data-asset-id="${sub.primary_video.asset_id}" controls playsinline preload="metadata" src="${esc(link.url)}"></video>`:`<div class="error">${esc(link?.playback_error||'原片暂时不可用')}</div>`}<div class="deliverables">${sub.support_assets.map(x=>`<div><div class="deliverable"><i data-lucide="file" width="16"></i><div><strong>${esc(x.title)}</strong><small>Asset #${x.asset_id}</small></div><span>${esc(assetRoles[x.role]||x.role)}</span></div>${x.text_preview?`<details data-detail-key="${esc(sub.submission_id)}:${x.asset_id}"><summary>查看内容摘要</summary><pre class="reply">${esc(x.text_preview)}</pre></details>`:''}</div>`).join('')||'<p class="meta">无配套交付件</p>'}</div>${!review&&sub.status==='ready'?`<div class="actions"><button class="primary" onclick="createSubmissionReview('${sub.submission_id}')"><i data-lucide="scan-eye" width="16"></i>交给酸辣土豆丝评审</button></div>`:''}${review?`<div class="meta">评审 ${esc(review.status)} · ${esc(review.review_id)}</div>`:''}</article>`}).join('')}
function renderExecutions(){const executions=(state.execs||[]).filter(ex=>!ex.prompt_version_id),form=state.session.transport==='hub'&&state.session.state==='calibrating'?`<div class="run-form"><h3>发起一次基准测试（可选）</h3><textarea id="testInstruction" placeholder="输入要 Agent 真实执行的单次任务；历史交付校准可留空"></textarea><div class="actions"><button class="primary" onclick="executeTest()">运行测试</button></div></div>`:'';if(!executions.length)return `${form}<p class="meta">尚未运行基准现场测试。历史交付校准无需使用这里。</p>`;return form+executions.map(ex=>`<article class="execution"><h3>${esc(ex.instruction)}</h3><div class="meta"><span>${esc(ex.status)}</span><span>${new Date(ex.created_at).toLocaleString()}</span><span>${ex.asset_ids.length} 个素材</span><span>${esc(ex.execution_id)}</span></div>${ex.response?`<div class="reply">${esc(ex.response)}</div>`:''}<div class="assets">${ex.asset_ids.map(id=>state.links[id]?.asset_type==='video'?`<video data-asset-id="${id}" controls preload="metadata" src="${esc(state.links[id].url)}"></video>`:`<div class="meta">${esc(state.links[id]?.title||`Asset #${id}`)}</div>`).join('')}</div></article>`).join('')}
function reviewErrorMessage(error){return error?.includes('report invalid after one repair')?'酸辣土豆丝已经完成分析，但返回的报告未通过结构校验。成片和证据仍然有效，可以重新生成评审报告。':error||'评审报告生成失败，可以重试。'}
function reviewBody(r){const p=r.report||{},title=r.status==='failed'?'评审报告生成失败':p.summary||'评审处理中';return `<div class="review-head"><div><h3>${esc(title)}</h3><div class="meta">${esc(r.status)} · ${esc(r.review_id)}</div></div>${p.total_score!==undefined?`<div class="score">${esc(p.total_score)}</div>`:''}</div>${p.verdict?`<p class="verdict">建议：${esc(p.verdict)}</p>`:''}${(p.hard_errors||[]).map(x=>`<div class="hard"><strong>硬错误</strong><br>${esc(x.problem||x.description||'')}<div class="meta">${esc(x.time_range||'')}</div></div>`).join('')}${(p.style_findings||[]).map(x=>`<div class="style"><strong>${esc(x.category||'风格观察')}</strong><br>${esc(x.observation||x.description||'')}<div class="meta">${esc(x.time_range||'')}</div></div>`).join('')}${r.status==='failed'?`<div class="error">${esc(reviewErrorMessage(r.error))}</div>`:''}`}
function renderReviews(){const reviews=baselineReviews();if(!reviews.length)return '<p class="meta">完成原始 creator 视频后，由你手动发起酸辣土豆丝评审。</p>';return reviews.map(r=>`<article class="execution">${reviewBody(r)}</article>`).join('')}
function renderFeedback(){const user=state.session.turns.filter(t=>t.actor==='user'&&['critique','note'].includes(t.kind)),critic=state.session.turns.filter(t=>t.actor==='evaluator');return `<div class="columns"><div><h3>你的主观反馈</h3>${user.map(turn).join('')||'<p class="meta">暂无反馈</p>'}<textarea id="feedbackText" placeholder="记录整体方向、动态感、节奏或事实问题"></textarea><button class="secondary" onclick="saveFeedback()"><i data-lucide="save" width="16"></i>保存反馈</button></div><div><h3>酸辣土豆丝评审</h3>${critic.map(turn).join('')||'<p class="meta">尚未完成 critic 评审</p>'}</div></div>`}
const turn=t=>`<div class="turn"><b>${esc(t.actor)} · ${new Date(t.created_at).toLocaleString()}</b>${esc(t.content)}</div>`;
function candidateTestForm(p,retry=false){const advised=p.managed_addendum?.includes('# ChatGPT calibration patch'),hint=advised?'留空会自动使用 ChatGPT 为这个候选制定的复测任务和验收标准；你填写的内容只会作为额外要求。':'留空时优先复用原测试题；没有原测试题时，系统会根据校准目标与验收标准生成。你无需填写。';return `<div class="candidate-test"><label for="candidateTest-${p.prompt_version_id}">${retry?'重试时的额外要求':'额外复测要求'}（可选）</label><textarea id="candidateTest-${p.prompt_version_id}" placeholder="例如：限定题材、时长、画幅或风格；留空由系统生成"></textarea><p class="meta">${hint}</p><div class="actions"><button class="primary" onclick="testCandidate('${p.prompt_version_id}')"><i data-lucide="${retry?'rotate-cw':'flask-conical'}" width="16"></i>${retry?'重新运行隔离复测':'启动隔离复测'}</button></div></div>`}
function candidatePackage(sub){const link=state.links[sub.primary_video.asset_id];return `<div class="candidate-output"><h4>候选版本产物</h4>${link?`<video data-asset-id="${sub.primary_video.asset_id}" controls preload="metadata" src="${esc(link.url)}"></video>`:`<div class="error">成片链接暂时不可用</div>`}<div class="deliverables">${sub.support_assets.map(x=>`<div><div class="deliverable"><i data-lucide="file" width="16"></i><div><strong>${esc(x.title)}</strong><small>Asset #${x.asset_id}</small></div><span>${esc(assetRoles[x.role]||x.role)}</span></div>${x.text_preview?`<details data-detail-key="candidate:${sub.submission_id}:${x.asset_id}"><summary>查看内容摘要</summary><pre class="reply">${esc(x.text_preview)}</pre></details>`:''}</div>`).join('')||'<p class="meta">本次没有配套交付件</p>'}</div></div>`}
function executionErrorMessage(error){if(!error)return'';if(error.includes('did not produce a playable video'))return'本次执行没有产出可播放视频，因此已按未完成处理。';if(error.includes('timed out after')||error.includes('execution exceeded'))return'清蒸土豆在时限内没有返回最终交付清单。系统已停止渲染进程；本次未登记文件不会自动算作通过。可以直接重试，系统会优先核验并复用与本次要求相符的已有成片。';return error}
function candidateExecutionRecord(context){const ex=context.execution;if(!ex)return'';const active=['queued','running'].includes(ex.status);return `<div class="candidate-output"><h4>隔离复测执行记录</h4><div class="meta"><span>第 ${context.attempts.length} 次尝试</span><span>${esc(ex.status)}</span><span>${new Date(ex.created_at).toLocaleString()}</span>${active?`<span data-elapsed-from="${esc(ex.created_at)}"></span>`:''}<span>${ex.asset_ids.length} 个已登记素材</span></div><details data-detail-key="candidate-instruction:${ex.execution_id}"><summary>查看本次复测要求</summary><pre class="reply">${esc(ex.instruction)}</pre></details>${ex.response?`<details data-detail-key="candidate-response:${ex.execution_id}"><summary>查看 Agent 最后输出${ex.status==='failed'?'（未完成）':''}</summary><pre class="reply">${esc(ex.response)}</pre></details>`:''}${ex.error?`<div class="error">${esc(executionErrorMessage(ex.error))}</div>`:''}<div class="assets">${ex.asset_ids.map(id=>`<div class="meta">${state.links[id]?.asset_type==='video'?'视频已归入“成片与交付” · ':''}${esc(state.links[id]?.title||`Asset #${id}`)}</div>`).join('')}</div></div>`}
function bindModules(){document.querySelectorAll('.module-head').forEach(btn=>btn.onclick=()=>{const mod=btn.closest('.module'),body=mod.querySelector('.module-body'),opening=!mod.classList.contains('open');if(!window.gsap||matchMedia('(prefers-reduced-motion: reduce)').matches){mod.classList.toggle('open',opening);return}if(opening){mod.classList.add('open');gsap.fromTo(body,{height:0,autoAlpha:0},{height:'auto',autoAlpha:1,duration:.28,ease:'power1.out',clearProps:'height,opacity,visibility'})}else{gsap.to(body,{height:0,autoAlpha:0,duration:.2,ease:'power1.in',onComplete:()=>{mod.classList.remove('open');gsap.set(body,{clearProps:'height,opacity,visibility'})}})}})}
function animateIn(){if(window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches)gsap.from('.module',{y:10,autoAlpha:0,duration:.32,stagger:.04,ease:'power1.out'})}
async function openImportDialog(){if(agent!=='creator'){alert('历史视频交付只能加入清蒸土豆校准');return}assetSource={};document.querySelector('#importError').textContent='';document.querySelector('#assetPreview').innerHTML='';document.querySelector('#importDialog').showModal();await loadAssetSources()}
async function loadAssetSources(){const select=document.querySelector('#assetSource'),picker=document.querySelector('#assetPicker');picker.innerHTML='<p class="meta">正在读取历史素材…</p>';try{const data=await api('/api/calibration-asset-sources');select.innerHTML=data.sources.map(x=>`<option value="${esc(x.source_id)}">${esc(x.title)} · ${x.video_count} 个视频 · ${x.available_asset_count} 个文件</option>`).join('');if(data.sources.length)await loadAssetSource();else picker.innerHTML='<p class="meta">素材库中没有可用视频。</p>'}catch(e){picker.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function loadAssetSource(){const sourceId=document.querySelector('#assetSource').value;if(!sourceId)return;const picker=document.querySelector('#assetPicker');picker.innerHTML='<p class="meta">正在整理交付件…</p>';try{assetSource=await api(`/api/calibration-asset-sources/${encodeURIComponent(sourceId)}`);const videos=assetSource.assets.filter(x=>x.asset_type==='video'),files=assetSource.assets.filter(x=>x.asset_type!=='video');picker.innerHTML=`<div class="asset-picker"><div class="asset-row"><span></span><b>主视频</b><small>单选</small></div>${videos.map(x=>`<label class="asset-row"><input type="radio" name="primaryAsset" value="${x.id}" ${x.id===assetSource.recommended_video_asset_id?'checked':''} ${x.available?'':'disabled'}><span><b>${esc(x.title)}</b><small>${x.duration_seconds?`${Math.round(x.duration_seconds)}s · `:''}Asset #${x.id}${x.available?'':' · 不可用'}</small></span>${x.available?`<button type="button" class="secondary" onclick="previewSourceAsset(event,${x.id},'video')"><i data-lucide="play" width="14"></i>预览</button>`:''}</label>`).join('')}<div class="asset-row"><span></span><b>配套交付件</b><small>可调整角色</small></div>${files.map(x=>`<label class="asset-row"><input class="supportAsset" type="checkbox" value="${x.id}" ${x.suggested_role!=='other'&&x.available?'checked':''} ${x.available?'':'disabled'}><span><b>${esc(x.title)}</b><small>${esc(x.mime_type)} · Asset #${x.id}${x.available?'':' · 不可用'}</small>${x.preview_available&&x.available?`<button type="button" class="dialog-close" onclick="previewSourceAsset(event,${x.id},'text')" aria-label="预览 ${esc(x.title)}"><i data-lucide="eye" width="14"></i></button>`:''}</span><select class="supportRole" data-asset="${x.id}" onclick="event.stopPropagation()">${Object.entries(assetRoles).map(([id,name])=>`<option value="${id}" ${id===x.suggested_role?'selected':''}>${name}</option>`).join('')}</select></label>`).join('')}</div>`;window.lucide?.createIcons()}catch(e){picker.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function previewSourceAsset(event,assetId,type){event.preventDefault();event.stopPropagation();const sourceId=document.querySelector('#assetSource').value,area=document.querySelector('#assetPreview');try{if(type==='video'){const link=await api(`/api/calibration-asset-sources/${encodeURIComponent(sourceId)}/assets/${assetId}/link`);area.innerHTML=`<video controls autoplay src="${esc(link.url)}"></video>`}else{const preview=await api(`/api/calibration-asset-sources/${encodeURIComponent(sourceId)}/assets/${assetId}/preview`);area.innerHTML=`<pre>${esc((preview.text_preview||'暂无可预览文本').slice(0,30000))}</pre>`}}catch(e){area.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function createImportedSubmission(){const button=document.querySelector('#importDialog .primary'),error=document.querySelector('#importError'),primary=document.querySelector('input[name="primaryAsset"]:checked'),sourceId=document.querySelector('#assetSource').value;if(!primary){error.textContent='请选择一个可用的主视频。';return}const support=[...document.querySelectorAll('.supportAsset:checked')].map(x=>({asset_id:Number(x.value),role:document.querySelector(`.supportRole[data-asset="${x.value}"]`).value})),parent=state.submissions?.[0]?.submission_id||null;button.disabled=true;button.textContent='加入中…';error.textContent='';try{await api(`/api/calibrations/${selected}/submissions`,{method:'POST',body:JSON.stringify({client_request_id:`ui-submission-${crypto.randomUUID()}`,primary_video_asset_id:Number(primary.value),support_assets:support,source_id:sourceId,parent_submission_id:parent})});closeDialog('importDialog');await refreshDetail()}catch(e){error.textContent=e.message}finally{button.disabled=false;button.textContent='加入校准'}}
async function executeTest(){const input=document.querySelector('#testInstruction'),button=input?.parentElement.querySelector('.primary'),instruction=input?.value.trim();if(!instruction)return;if(button){button.disabled=true;button.textContent='提交中…'}try{await api(`/api/calibrations/${selected}/executions`,{method:'POST',body:JSON.stringify({client_turn_id:`ui-test-${crypto.randomUUID()}`,instruction})});input.value='';await refreshDetail(true)}catch(e){alert(e.message)}finally{if(button){button.disabled=false;button.textContent='运行测试'}}}
async function createReview(executionId,assetId){try{await api(`/api/calibrations/${selected}/executions/${executionId}/reviews`,{method:'POST',body:JSON.stringify({client_request_id:`ui-${executionId}-${assetId}`,source_asset_id:assetId})});await refreshDetail()}catch(e){alert(e.message)}}
async function createSubmissionReview(submissionId,retry=false){try{const key=retry?`ui-review-${submissionId}-${crypto.randomUUID()}`:`ui-review-${submissionId}`;await api(`/api/calibrations/${selected}/submissions/${submissionId}/reviews`,{method:'POST',body:JSON.stringify({client_request_id:key})});activeCurrentTab='review';await refreshDetail(true)}catch(e){alert(e.message)}}
async function loadEvidence(reviewId){try{const e=await api(`/api/calibrations/${selected}/reviews/${reviewId}/evidence`);const area=document.querySelector('#evidenceArea');if(!area)return;area.innerHTML=`<div class="meta">${e.frames.length} 帧 · 转写 ${esc(e.transcript_status)}</div><div class="evidence-grid">${e.contact_sheets.map((x,i)=>`<figure><img src="${esc(x.url)}" alt="Contact sheet ${i+1}"><figcaption>Contact sheet ${i+1} · Asset #${x.asset_id}</figcaption></figure>`).join('')}${e.frames.map(x=>`<figure><img loading="lazy" src="${esc(x.url)}" alt="镜头 ${x.shot_index}"><figcaption>${esc(x.description)} · ${x.timestamp_seconds}s</figcaption></figure>`).join('')}</div>`}catch(e){const area=document.querySelector('#evidenceArea');if(area)area.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function loadCandidateEvidence(reviewId,containerId){const area=document.getElementById(containerId);if(!area)return;area.innerHTML='<p class="meta">正在加载候选成片证据…</p>';try{const e=await api(`/api/calibrations/${selected}/reviews/${reviewId}/evidence`);area.innerHTML=`<div class="meta">${e.frames.length} 帧 · 转写 ${esc(e.transcript_status)}</div><div class="evidence-grid">${e.contact_sheets.map((x,i)=>`<figure><img src="${esc(x.url)}" alt="候选 Contact sheet ${i+1}"><figcaption>Contact sheet ${i+1} · Asset #${x.asset_id}</figcaption></figure>`).join('')}${e.frames.map(x=>`<figure><img loading="lazy" src="${esc(x.url)}" alt="镜头 ${x.shot_index}"><figcaption>${esc(x.description)} · ${x.timestamp_seconds}s</figcaption></figure>`).join('')}</div>`}catch(e){area.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function loadPromptDraft(promptVersionId){const area=document.querySelector('#promptDraftPreview');if(!area)return;area.innerHTML='<p class="meta">正在读取完整 Prompt 草案…</p>';try{const draft=await api(`/api/admin/agents/${agent}/prompt-versions/${promptVersionId}`);area.innerHTML=`<details open data-detail-key="full-prompt:${esc(promptVersionId)}"><summary>完整 Prompt 草案 · ${esc(draft.content_sha256.slice(0,12))}</summary><pre class="full-prompt-preview">${esc(draft.content)}</pre></details>`}catch(e){area.innerHTML=`<div class="error">${esc(e.message||'Prompt 草案暂时无法读取')}</div>`}}
async function saveFeedback(){const input=document.querySelector('#feedbackText'),content=input.value.trim();if(!content)return;await api(`/api/calibrations/${selected}/turns`,{method:'POST',body:JSON.stringify({client_turn_id:`ui-feedback-${Date.now()}`,actor:'user',kind:'critique',content})});input.value='';await refreshDetail(true)}
function goToCandidateTest(promptVersionId){const field=document.querySelector(`#candidateTest-${promptVersionId}`);if(!field)return;field.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});setTimeout(()=>field.focus({preventScroll:true}),250)}
function commanderTaskText(advisory){return advisory?.advisory_id?`完成校准任务 ${advisory.advisory_id}。`:'完成最新校准任务。'}
function showChatGptHandoff(advisoryId=''){const advisory=(state.advisories||[]).find(x=>x.advisory_id===advisoryId)||latestAdvisory();if(!advisory)return;document.querySelector('#chatGptCommand').textContent=commanderTaskText(advisory);document.querySelector('#chatGptTaskId').textContent=`Task ${advisory.advisory_id}`;const source=latestAdvisorySource();document.querySelector('#chatGptTaskMeta').textContent=source?`视频 ${source.submission.submission_id}、你的反馈与评审 ${source.review.review_id} 已绑定。`:'当前证据包已绑定。';document.querySelector('#chatGptDialog').showModal();window.lucide?.createIcons()}
async function copyChatGptTask(button){const text=document.querySelector('#chatGptCommand')?.textContent?.trim();if(!text)return false;try{await navigator.clipboard.writeText(text);if(button){const old=button.innerHTML;button.innerHTML='<i data-lucide="check" width="15"></i>已复制';window.lucide?.createIcons();setTimeout(()=>{button.innerHTML=old;window.lucide?.createIcons()},1600)}return true}catch{alert(text);return false}}
async function copyAndOpenChatGpt(button){await copyChatGptTask(button);window.open('https://chatgpt.com/','_blank','noopener,noreferrer')}
async function createAdvisory(){if(analysisRequestBusy)return;const source=latestAdvisorySource();if(!source){alert('请先完成候选成片的酸辣土豆丝评审。');return}analysisRequestBusy=true;activeCurrentTab='prompt';try{const advisory=await api(`/api/calibrations/${selected}/advisories`,{method:'POST',body:JSON.stringify({client_request_id:`ui-advisory-${crypto.randomUUID()}`,submission_id:source.submission.submission_id,review_id:source.review.review_id})});await refreshDetail(true);showChatGptHandoff(advisory.advisory_id)}catch(e){alert(e.message||'无法建立 ChatGPT 校准任务')}finally{analysisRequestBusy=false}}
async function testCandidate(promptVersionId){const input=document.querySelector(`#candidateTest-${promptVersionId}`),instruction=input?.value.trim()||'',button=input.parentElement.querySelector('.primary'),original=button.innerHTML;button.disabled=true;button.textContent='生成并排队中…';try{await api(`/api/calibrations/${selected}/prompt-candidates/${promptVersionId}/tests`,{method:'POST',body:JSON.stringify({client_turn_id:`ui-candidate-test-${crypto.randomUUID()}`,instruction})});await refreshDetail(true)}catch(e){alert(e.message);button.disabled=false;button.innerHTML=original;window.lucide?.createIcons()}}
async function activateCandidate(promptVersionId,hash){if(!confirm('确认把这个已通过复测门禁的候选版本设为正式 Prompt？当前正式版本会保留，可随时回滚。'))return;try{await api(`/api/admin/agents/${agent}/prompt-versions/${promptVersionId}/promote`,{method:'POST',body:JSON.stringify({confirm_content_sha256:hash})});await refreshDetail(true)}catch(e){alert(e.message)}}
async function rollbackCandidate(promptVersionId,hash){if(!confirm('确认回滚到这个历史 Prompt 版本？当前版本会被保留为历史记录。'))return;try{await api(`/api/admin/agents/${agent}/prompt-versions/${promptVersionId}/rollback`,{method:'POST',body:JSON.stringify({confirm_content_sha256:hash})});await refreshDetail(true)}catch(e){alert(e.message)}}
window.addEventListener('focus',()=>{if(selected&&latestAdvisory()?.status==='pending')refreshDetail(false)});setInterval(updateElapsed,1000);boot();
</script></body></html>'''
